package com.primehr.performancemanagement.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity@Table(name="spms_commitment_cascade",uniqueConstraints=@UniqueConstraint(name="uk_spms_commitment_cascade",columnNames={"agency_id","upstream_item_id","downstream_item_id","mode"}))public class PerformanceCommitmentCascade extends RspAuditedEntity{public enum Mode{REFERENCE_ONLY,RESPONSIBILITY_SHARE}@Column(name="upstream_item_id",nullable=false,length=36)private String upstreamItemId;@Column(name="downstream_item_id",nullable=false,length=36)private String downstreamItemId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Mode mode;@Column(name="share_percent",precision=7,scale=4)private BigDecimal sharePercent;@Column(nullable=false)private boolean active;@Column(name="source_fingerprint",nullable=false,length=64)private String sourceFingerprint;protected PerformanceCommitmentCascade(){}public PerformanceCommitmentCascade(String a,String up,String down,Mode mode,BigDecimal share,String fp){super(a);upstreamItemId=requiredText(up,"upstreamItemId");downstreamItemId=requiredText(down,"downstreamItemId");this.mode=mode;sharePercent=share;active=true;sourceFingerprint=requiredText(fp,"sourceFingerprint");if(mode==Mode.RESPONSIBILITY_SHARE&&(share==null||share.signum()<=0||share.compareTo(new BigDecimal("100.0000"))>0))throw new IllegalArgumentException("Responsibility share must be above zero and at most 100.0000");if(mode==Mode.REFERENCE_ONLY&&share!=null)throw new IllegalArgumentException("Reference-only cascades cannot have a share");}public String getUpstreamItemId(){return upstreamItemId;}public String getDownstreamItemId(){return downstreamItemId;}public Mode getMode(){return mode;}public BigDecimal getSharePercent(){return sharePercent;}public boolean isActive(){return active;}public String getSourceFingerprint(){return sourceFingerprint;}}
